"use client";

import * as React from "react";
import { cn } from "cn";
import { Popover as PopoverPrimitive, Slot } from "radix-ui";

import { useV4PortalContainer } from "../scope";

import { useOwnedEscape } from "../lib/use-owned-escape";

import menu from "./menu.module.css";

function Popover({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Root>) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />;
}

const PopoverTrigger = React.forwardRef<
  React.ElementRef<typeof PopoverPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Trigger>
>(({ ...props }, ref) => {
  return <PopoverPrimitive.Trigger ref={ref} data-slot="popover-trigger" {...props} />;
});
PopoverTrigger.displayName = "PopoverTrigger";

const PopoverContent = React.forwardRef<
  React.ComponentRef<typeof PopoverPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Content> & { surface?: "card" | "menu" }
>(
  (
    {
      className,
      collisionPadding = 8,
      align = "center",
      sideOffset = 4,
      surface = "card",
      onEscapeKeyDown,
      ...props
    },
    ref
  ) => {
    const escape = useOwnedEscape(ref, onEscapeKeyDown);
    return (
      <PopoverPrimitive.Portal container={useV4PortalContainer()}>
        <PopoverPrimitive.Content
          ref={escape.ref}
          data-slot="popover-content"
          collisionPadding={collisionPadding}
          align={align}
          sideOffset={sideOffset}
          data-surface={surface}
          className={cn(
            "z-50",
            menu.surface,
            surface === "menu" ? menu.panel : menu.card,
            menu.motion,
            className
          )}
          {...props}
          onEscapeKeyDown={escape.onEscapeKeyDown}
        />
      </PopoverPrimitive.Portal>
    );
  }
);
PopoverContent.displayName = "PopoverContent";

const PopoverAnchor = React.forwardRef<
  React.ElementRef<typeof PopoverPrimitive.Anchor>,
  React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Anchor>
>(({ asChild, virtualRef, ...props }, ref) => {
  const node = React.useRef<HTMLDivElement | null>(null);
  const attach = React.useCallback(
    (element: HTMLDivElement | null) => {
      node.current = element;
      if (typeof ref === "function") ref(element);
      else if (ref) {
        // eslint-disable-next-line no-param-reassign -- React attaches forwarded object refs by mutation.
        ref.current = element;
      }
    },
    [ref]
  );
  if (virtualRef)
    return (
      <PopoverPrimitive.Anchor
        ref={ref}
        data-slot="popover-anchor"
        virtualRef={virtualRef}
        hidden
        {...props}
      />
    );
  // Radix registers a real anchor only when its node attaches, and its trigger re-mounts without
  // the anchor wrapper once a custom anchor exists, so the popper measures through a virtual ref.
  const Comp = asChild ? Slot.Root : "div";
  return (
    <>
      <Comp ref={attach} data-slot="popover-anchor" {...props} />
      <PopoverPrimitive.Anchor virtualRef={node} hidden />
    </>
  );
});
PopoverAnchor.displayName = "PopoverAnchor";

const PopoverHeader = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="popover-header"
      className={cn("flex flex-col gap-0.5", className)}
      {...props}
    />
  );
});
PopoverHeader.displayName = "PopoverHeader";

const PopoverTitle = React.forwardRef<HTMLHeadingElement, React.ComponentPropsWithoutRef<"h2">>(
  ({ className, children, ...props }, ref) => (
    <h2 ref={ref} data-slot="popover-title" className={cn("", className)} {...props}>
      {children}
    </h2>
  )
);
PopoverTitle.displayName = "PopoverTitle";

const PopoverDescription = React.forwardRef<
  React.ComponentRef<"p">,
  React.ComponentPropsWithoutRef<"p">
>(({ className, ...props }, ref) => {
  return (
    <p
      ref={ref}
      data-slot="popover-description"
      className={cn("text-muted-foreground", className)}
      {...props}
    />
  );
});
PopoverDescription.displayName = "PopoverDescription";

export {
  Popover,
  PopoverAnchor,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger
};

.surface {
  box-sizing: border-box;
  border-radius: calc(var(--v4-radius-pop) * var(--corners));
  background-color: var(--v4-pop);
  color: var(--v4-ink);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-pop-line),
    var(--v4-shadow-pop);
  outline: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.panel {
  min-width: min(
    max(var(--v4-size-menu-min), var(--radix-popper-anchor-width, 0px)),
    var(--radix-popper-available-width, 100vw)
  );
  max-width: min(
    var(--v4-size-menu-max),
    var(--radix-popper-available-width, calc(100vw - 2 * var(--v4-space-16)))
  );
  max-height: var(--radix-popper-available-height, none);
  overflow-x: hidden;
  overflow-y: auto;
}
.sub {
  min-width: var(--v4-size-menu-min);
}
.card {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-8);
  width: min(var(--v4-size-popover), var(--radix-popper-available-width, 100vw));
  max-height: var(--radix-popper-available-height, none);
  overflow-y: auto;
  padding: var(--v4-space-12);
}
.tooltip {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-8);
  width: fit-content;
  max-width: min(var(--v4-size-menu-max), var(--radix-popper-available-width, 100vw));
  padding: var(--v4-space-6) var(--v4-space-8);
  border-radius: calc(var(--v4-radius-sm) * var(--corners));
  background-color: var(--v4-ink);
  color: var(--v4-on-ink);
  box-shadow: var(--v4-shadow-pop);
  overflow-wrap: break-word;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.tooltip:has([data-slot="kbd"]) {
  padding-inline-end: var(--v4-space-6);
}
.tooltipArrow {
  fill: var(--v4-ink);
}

.motion {
  --v4-pop-from: 0 0;
  transform-origin: var(--radix-popper-transform-origin, center);
}
.motion[data-side="bottom"] {
  --v4-pop-from: 0 calc(-1 * var(--v4-space-4));
}
.motion[data-side="top"] {
  --v4-pop-from: 0 var(--v4-space-4);
}
.motion[data-side="right"] {
  --v4-pop-from: calc(-1 * var(--v4-space-4)) 0;
}
.motion[data-side="left"] {
  --v4-pop-from: var(--v4-space-4) 0;
}
.motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]) {
  animation: popIn var(--v4-duration-fast) var(--v4-ease-spring) both;
}
.motion[data-state="closed"] {
  animation: popOut var(--v4-duration-exit-fast) var(--v4-ease-exit) both;
}
.tooltip.motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]) {
  animation-name: tipIn;
}
.tooltip.motion[data-state="closed"] {
  animation-name: tipOut;
}
@keyframes popIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes popOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes tipIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes tipOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]),
  .tooltip.motion:is(
      [data-state="open"],
      [data-state="delayed-open"],
      [data-state="instant-open"]
    ) {
    animation-name: fadeIn;
  }
  .motion[data-state="closed"],
  .tooltip.motion[data-state="closed"] {
    animation-name: fadeOut;
  }
}

.inset {
  --v4-menu-icon-slot: 0px;
  padding: var(--v4-space-4);
}
.inset:has(.row > :is(svg, [data-menu-icon]):not(.trail), .row[data-inset], .label[data-inset]) {
  --v4-menu-icon-slot: calc(var(--v4-size-icon) + var(--v4-space-8));
}

.list {
  max-height: calc(9 * var(--v4-size-control-sm));
  overflow-x: hidden;
  overflow-y: auto;
  outline: none;
  scroll-padding-block: var(--v4-space-4);
}

.row {
  position: relative;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  min-width: 0;
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-6) var(--v4-space-8);
  padding-inline-start: calc(var(--v4-space-8) + var(--v4-menu-icon-slot, 0px));
  border-radius: calc(var(--v4-radius-sm) * var(--corners));
  overflow: hidden;
  color: var(--v4-ink);
  white-space: nowrap;
  cursor: default;
  user-select: none;
  outline: none;
  text-decoration: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.row:has(> :is(svg, [data-menu-icon]):not(.trail)) {
  padding-inline-start: var(--v4-space-8);
}
.row > svg,
.row > [data-menu-icon] {
  flex: none;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  pointer-events: none;
}
.row:is(
    [data-highlighted],
    [data-selected="true"],
    [data-active],
    [data-state="open"],
    a:hover,
    a:focus-visible
  ) {
  background-color: var(--v4-select);
}
.row:is([data-variant="destructive"], [data-danger]) {
  color: var(--v4-bad);
}
.row:is([data-variant="destructive"], [data-danger]):is(
    [data-highlighted],
    [data-selected="true"]
  ) {
  background-color: var(--v4-action-danger-surface);
}
.row:is([data-disabled]:not([data-disabled="false"]), [aria-disabled="true"]) {
  color: var(--v4-faint);
  background-color: transparent;
  pointer-events: none;
}
.indicator {
  order: 1;
  display: flex;
  flex: none;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  align-items: center;
  justify-content: center;
  margin-inline-start: auto;
  pointer-events: none;
}
.indicator > svg {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.indicator ~ :is(.shortcut, .meta) {
  margin-inline-start: 0;
}
.row:not([data-checked="true"]) > .indicator[data-command] {
  visibility: hidden;
}
.text {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
}
.title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.description {
  min-width: 0;
  overflow: hidden;
  color: var(--v4-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.shortcut,
.meta {
  order: 2;
  margin-inline-start: auto;
  padding-inline-start: var(--v4-space-8);
  color: var(--v4-muted);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.shortcut {
  display: inline-flex;
  flex: none;
  align-items: center;
}
.meta {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 45%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.meta + .shortcut {
  margin-inline-start: 0;
}
.trail {
  order: 3;
  flex: none;
  margin-inline-start: auto;
  color: var(--v4-muted);
}
.label,
.group > [cmdk-group-heading] {
  display: block;
  padding: var(--v4-space-6) var(--v4-space-8);
  padding-inline-start: calc(var(--v4-space-8) + var(--v4-menu-icon-slot, 0px));
  color: var(--v4-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.label:not(:first-child, .separator + *),
:is([role="group"], [cmdk-group]):not(:first-child)
  > :is(.label, [cmdk-group-heading]):first-child {
  margin-top: var(--v4-space-4);
  padding-top: calc(var(--v4-space-6) + var(--v4-space-4));
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.separator {
  height: var(--v4-size-control-border);
  margin: var(--v4-space-4) 0;
  border: 0;
  background-color: var(--v4-line-soft);
}
.empty {
  padding: var(--v4-space-16) var(--v4-space-8);
  color: var(--v4-muted);
  text-align: center;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--v4-space-4);
  padding: var(--v4-space-4);
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.hints {
  container-type: inline-size;
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-4) var(--v4-space-12);
  overflow: hidden;
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.hint {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-4);
}
.hintsExtra {
  min-width: 0;
  margin-inline-start: auto;
  overflow: hidden;
  text-overflow: ellipsis;
}
@container (max-width: 360px) {
  .hint:nth-child(n + 2) {
    display: none;
  }
}
@container (max-width: 200px) {
  .hint {
    display: none;
  }
}

.navItem {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--v4-space-control-gap);
  box-sizing: border-box;
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-6) var(--v4-space-control-inline-sm);
  border-radius: calc(var(--v4-radius-control) * var(--corners));
  background-color: transparent;
  color: var(--v4-ink);
  white-space: nowrap;
  text-decoration: none;
  transition-property: background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-type-label-font-size);
  line-height: var(--v4-type-label-line-height);
  font-weight: var(--v4-type-label-font-weight);
  letter-spacing: var(--v4-type-label-letter-spacing);
}
.navItem:is(:hover, [data-state="open"], [data-active]) {
  background-color: var(--v4-select);
}
.navItem:disabled {
  opacity: 0.5;
  pointer-events: none;
}
.navChevron {
  width: var(--v4-size-icon-xs);
  height: var(--v4-size-icon-xs);
  transition-property: rotate;
  transition-duration: var(--v4-duration-moderate);
  transition-timing-function: var(--v4-ease-standard);
}
.navItem[data-state="open"] > .navChevron {
  rotate: 180deg;
}
.navViewportAnchor {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 50;
  display: flex;
  padding-top: var(--v4-space-4);
  translate: var(--v4-nav-viewport-x, 0) 0;
}
.navViewportAnchor[data-placed] {
  transition-property: translate;
  transition-duration: var(--v4-duration-moderate);
  transition-timing-function: var(--v4-ease-standard);
}
.navViewport {
  position: relative;
  overflow: hidden;
  width: var(--radix-navigation-menu-viewport-width);
  height: var(--radix-navigation-menu-viewport-height);
  max-width: min(calc(100vw - 2 * var(--v4-space-16)), var(--v4-size-measure-form));
  transform-origin: top left;
}
.navContent {
  position: absolute;
  top: 0;
  left: 0;
  box-sizing: border-box;
  width: max-content;
  min-width: var(--v4-size-menu-min);
  max-width: min(calc(100vw - 2 * var(--v4-space-16)), var(--v4-size-measure-form));
}
@media (prefers-reduced-motion: reduce) {
  .navViewportAnchor[data-placed],
  .navChevron {
    transition: none;
  }
}
